import{_ as a,o as r,c as n,a4 as i}from"./chunks/framework.cM03Lg2X.js";const b=JSON.parse('{"title":"算子工程方法","description":"从瓶颈判断、HBM 访问与 Shape 稳定性出发的 CUDA/Triton 算子开发方法。","frontmatter":{"title":"算子工程方法","description":"从瓶颈判断、HBM 访问与 Shape 稳定性出发的 CUDA/Triton 算子开发方法。"},"headers":[],"relativePath":"ai-infra/operator-engineering.md","filePath":"ai-infra/operator-engineering.md","lastUpdated":1786332289000}'),o={name:"ai-infra/operator-engineering.md"};function l(t,e,h,d,p,c){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="算子工程方法" tabindex="-1">算子工程方法 <a class="header-anchor" href="#算子工程方法" aria-label="Permalink to “算子工程方法”">​</a></h1><p>写自定义算子的首要任务不是立即写 kernel，而是证明现有实现的瓶颈在哪里，以及专用实现能减少哪一部分真实成本。</p><h2 id="写代码前的三个问题" tabindex="-1">写代码前的三个问题 <a class="header-anchor" href="#写代码前的三个问题" aria-label="Permalink to “写代码前的三个问题”">​</a></h2><h3 id="_1-是-memory-bound、compute-bound-还是-launch-bound" tabindex="-1">1. 是 memory-bound、compute-bound 还是 launch-bound？ <a class="header-anchor" href="#_1-是-memory-bound、compute-bound-还是-launch-bound" aria-label="Permalink to “1. 是 memory-bound、compute-bound 还是 launch-bound？”">​</a></h3><ul><li><strong>memory-bound</strong>：主要时间花在数据搬运，常见于逐元素运算、归一化和小规模 reduction。</li><li><strong>compute-bound</strong>：计算单元长期饱和，常见于足够大的矩阵乘。</li><li><strong>launch-bound</strong>：单个 kernel 很小，启动与调度开销占比过高。</li></ul><p>Roofline Model 用 Operational Intensity（单位数据搬运对应的计算量）帮助区分前两类；Profiler 的 kernel 时间、带宽、占用率和调用数量用于验证判断。</p><h3 id="_2-数据是否重复进出-hbm" tabindex="-1">2. 数据是否重复进出 HBM？ <a class="header-anchor" href="#_2-数据是否重复进出-hbm" aria-label="Permalink to “2. 数据是否重复进出 HBM？”">​</a></h3><p>多个 eager op 之间若不断读写中间结果，算术量不大也可能很慢。Fusion 的价值在于减少中间张量和 HBM 往返，但只有在寄存器、shared memory、并行度与编译开销可控时才值得。</p><p>RMSNorm、LayerNorm、bias + activation、optimizer step 和 LoRA 更新都是适合练习融合的场景。</p><h3 id="_3-shape-是否稳定" tabindex="-1">3. Shape 是否稳定？ <a class="header-anchor" href="#_3-shape-是否稳定" aria-label="Permalink to “3. Shape 是否稳定？”">​</a></h3><p>固定 shape 更容易针对性调块、展开和选择并行策略；动态 shape 需要 shape bucket、通用 fallback 和更完整的 benchmark。Prefill attention 与 decode attention 的序列形态和瓶颈不同，通常不应被视为同一个优化问题。</p><h2 id="推荐工作流" tabindex="-1">推荐工作流 <a class="header-anchor" href="#推荐工作流" aria-label="Permalink to “推荐工作流”">​</a></h2><ol><li>明确 PyTorch 或现有库 baseline，固定输入、精度和硬件。</li><li>写 reference implementation，先保证可比较的正确性。</li><li>实现最简单 kernel，不提前堆优化技巧。</li><li>用真实 workload profile，而不是只看合成微基准。</li><li>根据瓶颈选择 coalescing、tiling、fusion、reduction 或专用 shape。</li><li>覆盖误差、边界 shape、非连续内存、不同 dtype 和回退路径。</li><li>验证端到端收益；单 kernel 更快不代表整条模型链路更快。</li></ol><h2 id="容易误判的指标" tabindex="-1">容易误判的指标 <a class="header-anchor" href="#容易误判的指标" aria-label="Permalink to “容易误判的指标”">​</a></h2><ul><li>Shared memory 更多不一定更快，可能降低 occupancy。</li><li>Occupancy 更高不一定更快，带宽或指令吞吐可能早已饱和。</li><li>量化与稀疏不天然等于加速，格式转换、反量化和不规则访问会抵消收益。</li><li>Triton 降低了 kernel 开发门槛，但仍需要理解内存层次、并行映射和 shape 假设。</li></ul><h2 id="生产化验收" tabindex="-1">生产化验收 <a class="header-anchor" href="#生产化验收" aria-label="Permalink to “生产化验收”">​</a></h2><p>生产算子的难点还包括 PyTorch 集成、自动求导、设备与 dtype 兼容、数值误差、构建发布和回退机制。性能、正确性和可部署性缺一不可。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li><a href="https://app.notion.com/p/AI-Infra-CUDA-Mode-Notes-36f3a54bd6b481e182baf9814158a976" target="_blank" rel="noreferrer">Notion：AI Infra 算子开发经验总结</a></li><li><a href="https://app.notion.com/p/01-HBM-Shape-36f3a54bd6b481aab612f04dbc21d15e" target="_blank" rel="noreferrer">Notion：写算子前先问三个问题</a></li></ul>',19)])])}const m=a(o,[["render",l]]);export{b as __pageData,m as default};
